const task = $input.first()?.json ?? {};

if (!task.id) {
  throw new Error(
    'Manual Test: no se encontró una tarea clinical_tasks con status=pending_review.'
  );
}

return [{
  json: {
    clinical_task_id: task.id,
    patient_id: task.patient_id || null,
    source_alert_id: task.source_alert_id || null,
    source_event_id: task.source_event_id || task.event_id || null,
    source_channel: 'n8n',
    force_generate: true,
    ollama_base_url: 'http://ollama:11434',
    ollama_model: 'gpt-oss:20b'
  }
}];

const input = $input.first()?.json ?? {};

function norm(value) {
  if (value === undefined || value === null) return null;
  const text = String(value).trim();
  if (!text || ['null', 'undefined'].includes(text.toLowerCase())) return null;
  return text;
}

const clinicalTaskId = norm(input.clinical_task_id || input.task_id);
const uuidRegex =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!clinicalTaskId) {
  throw new Error('Flow-CLN-04 requiere clinical_task_id.');
}

if (!uuidRegex.test(clinicalTaskId)) {
  throw new Error(
    `clinical_task_id inválido: "${clinicalTaskId}". Se esperaba UUID de clinical_tasks.id.`
  );
}

return [{
  json: {
    clinical_task_id: clinicalTaskId,
    patient_id: norm(input.patient_id),
    source_alert_id: norm(input.source_alert_id),
    source_event_id: norm(input.source_event_id),
    source_channel: norm(input.source_channel) || 'n8n',
    force_generate: Boolean(input.force_generate),
    ollama_base_url: (norm(input.ollama_base_url) || 'http://ollama:11434').replace(/\/+$/, ''),
    ollama_model: norm(input.ollama_model) || 'gpt-oss:20b'
  }
}];

const context = $input.first().json;
const task = context.task || {};
const force = Boolean(context.force_generate);

if (task.status === 'closed') {
  return [{ json: { ...context, should_generate: false, skip_reason: 'task_closed' } }];
}

const reusable = ['generated', 'approved', 'edited'].includes(task.ai_draft_status);

return [{
  json: {
    ...context,
    should_generate: force || !reusable,
    skip_reason: (!force && reusable) ? 'current_draft_exists' : null
  }
}];

const context = $('Decide Whether To Generate').first().json;
const runtime = $('Normalize AI Draft Trigger').first().json;
const ollamaBaseUrl = runtime.ollama_base_url || 'http://ollama:11434';
const ollamaModel = runtime.ollama_model || 'gpt-oss:20b';

const systemPrompt = `Eres un asistente de apoyo para un profesional de salud que revisa una tarea de seguimiento ambulatorio de diabetes.

Genera únicamente un BORRADOR para revisión profesional.

Reglas obligatorias:
- No diagnostiques.
- No prescribas.
- No cambies medicamentos ni indiques dosis.
- No emitas una instrucción final al paciente.
- No inventes datos, síntomas, antecedentes, fuentes ni guías.
- Usa exclusivamente los datos incluidos en el contexto.
- Si falta información, decláralo explícitamente.
- Separa hechos observados, preguntas pendientes y acciones de revisión profesional.
- Las acciones sugeridas deben ser acciones de verificación/revisión humana, no decisiones terapéuticas automáticas.
- source_citations solo puede contener source_key del source_registry proporcionado. Estas claves representan procedencia de datos internos, no referencias bibliográficas.
- La salida debe estar en español.
- Devuelve únicamente JSON válido, sin Markdown ni texto adicional.`;

const schema = {
  type: 'object',
  additionalProperties: false,
  properties: {
    draft_text: { type: 'string' },
    summary: { type: 'string' },
    observations: { type: 'array', items: { type: 'string' } },
    pending_questions: { type: 'array', items: { type: 'string' } },
    suggested_review_actions: { type: 'array', items: { type: 'string' } },
    safety_flags: { type: 'array', items: { type: 'string' } },
    source_citations: { type: 'array', items: { type: 'string' } }
  },
  required: [
    'draft_text',
    'summary',
    'observations',
    'pending_questions',
    'suggested_review_actions',
    'safety_flags',
    'source_citations'
  ]
};

const payload = {
  clinical_task: {
    id: context.task.id,
    trigger_rule: context.task.trigger_rule,
    priority: context.task.priority,
    status: context.task.status,
    source_alert_id: context.task.source_alert_id,
    created_at: context.task.created_at
  },
  patient_history: context.patient_history,
  glucose_readings: context.glucose_readings,
  daily_context: context.daily_context,
  adherence_summary: context.adherence_summary,
  alerts: context.alerts,
  source_registry: context.source_registry
};

const request_body = {
  model: ollamaModel,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: JSON.stringify(payload) }
  ],
  stream: false,
  format: schema,
  options: { temperature: 0.2 }
};

return [{
  json: {
    ...context,
    prompt_version: 'clinical-support-db-v2',
    provider: 'ollama',
    model: ollamaModel,
    ollama_base_url: ollamaBaseUrl,
    request_body
  }
}];

const response = $input.first()?.json ?? {};
const statusCode = Number(response.statusCode ?? response.status ?? 200);
const body = response.body && typeof response.body === 'object'
  ? response.body
  : response;

const outputText = body.message?.content || body.response || null;
const base = $('Build Grounded Clinical Prompt').first().json;

if (statusCode >= 400 || !outputText) {
  const err = body.error?.message || body.error ||
    `Ollama respondió ${statusCode} sin contenido estructurado.`;
  return [{ json: { ...base, ai_ok: false, error_message: String(err) } }];
}

let parsed;
try {
  parsed = typeof outputText === 'string' ? JSON.parse(outputText) : outputText;
} catch {
  return [{
    json: {
      ...base,
      ai_ok: false,
      error_message: 'La respuesta de Ollama no se pudo interpretar como JSON.'
    }
  }];
}

const arrays = [
  'observations',
  'pending_questions',
  'suggested_review_actions',
  'safety_flags',
  'source_citations'
];

if (
  typeof parsed.draft_text !== 'string' ||
  !parsed.draft_text.trim() ||
  typeof parsed.summary !== 'string' ||
  arrays.some((key) => !Array.isArray(parsed[key]))
) {
  return [{
    json: {
      ...base,
      ai_ok: false,
      error_message: 'La salida estructurada de Ollama no cumple el contrato del borrador clínico.'
    }
  }];
}

const allowed = new Set((base.source_registry || []).map((s) => s.source_key));
const sourceKeys = parsed.source_citations.filter(
  (key) => typeof key === 'string' && allowed.has(key)
);

return [{
  json: {
    ...base,
    ai_ok: true,
    draft_text: parsed.draft_text.trim(),
    structured_output: parsed,
    source_keys: sourceKeys,
    generated_at: new Date().toISOString()
  }
}];
